export const TRACKS={'menu-tower':'menu-tower','menu-den':'menu-den','menu-survival':'menu-survival','menu-pvp':'menu-pvp','menu-gacha':'menu-gacha','menu-conquest':'menu-conquest',invocation:'invocation',home:'sanctuary',tower:'sanctuary',pvp:'sanctuary',collection:'sanctuary',team:'sanctuary',inventory:'sanctuary',friends:'sanctuary',profile:'sanctuary',gacha:'summon',survival:'survival',arena:'battle',battle:'battle',den:'raid-battle',raid:'raid-battle',afk:'menu-pokeclick',conquest:'conquest',storm:'storm',cosmic:'cosmic',forest:'forest',victory:'victory',defeat:'den'};
export class MusicPlayer{
 constructor(g){this.g=g;this.scene='home';this.cache=new Map();this.unlocked=false;this.holds=new Set();this.current=null;this.retiring=null;this.activeTrack=null;this.abort=new AbortController();const signal=this.abort.signal;const unlock=()=>this.unlock();document.addEventListener('pointerdown',unlock,{signal});document.addEventListener('keydown',e=>{if(e.code==='KeyM'&&!/INPUT|SELECT|TEXTAREA/.test(e.target.tagName)&&!e.ctrlKey&&!e.altKey){e.preventDefault();this.toggle()}else this.unlock()},{signal});for(const key of ['sanctuary','menu-tower','menu-den','menu-survival','menu-pvp','menu-gacha','menu-conquest','menu-pokeclick','invocation','raid-battle'])this.prepare(key);setTimeout(()=>this.unlock(),0);document.addEventListener('pointerover',e=>{const page=e.target.closest?.('[data-page]')?.dataset.page;if(page)this.prepare(TRACKS['menu-'+page]||TRACKS[page]||'sanctuary')},{signal});document.addEventListener('visibilitychange',()=>{if(document.hidden){this.current?.pause();this.retiring?.pause()}else this.refresh()},{signal})}
 prepare(key){if(this.cache.has(key))return this.cache.get(key);const audio=new Audio('assets/music/'+key+'.wav');audio.loop=true;audio.preload='auto';audio.load();this.cache.set(key,audio);return audio}
 unlock(){this.unlocked=true;this.refresh()}
 setScene(scene){this.scene=scene;this.prepare(TRACKS[scene]||'sanctuary');this.refresh()}
 refresh(){this.updateButton();if(!this.unlocked||!this.g.state.settings.music||document.hidden||this.holds.size){this.current?.pause();this.retiring?.pause();return}const key=TRACKS[this.scene]||'sanctuary';if(this.activeTrack===key&&this.current){this.current.play().catch(()=>{});return}this.switchTo(key)}
 switchTo(key){const version=this.switchVersion=(this.switchVersion||0)+1;cancelAnimationFrame(this.fade);this.retiring?.pause();const old=this.current;this.retiring=old;const next=this.current=this.prepare(key);this.activeTrack=key;next.loop=true;next.preload='auto';next.volume=this.g.state.settings.music?this.g.state.settings.musicVolume*.3:0;next.play().then(()=>{if(next!==this.current||version!==this.switchVersion){if(next!==this.current)next.pause();return}if(this.holds.size||document.hidden||!this.g.state.settings.music){next.pause();old?.pause();return}const start=performance.now(),oldVolume=old?.volume||0;const frame=t=>{if(next!==this.current||version!==this.switchVersion)return;const p=Math.max(0,Math.min(1,(t-start)/180)),volume=this.g.state.settings.musicVolume;next.volume=this.g.state.settings.music?volume*(.3+.7*p):0;if(old)old.volume=oldVolume*(1-p);if(p<1&&!document.hidden)this.fade=requestAnimationFrame(frame);else{old?.pause();if(this.retiring===old)this.retiring=null;next.volume=this.g.state.settings.music?volume:0}};this.fade=requestAnimationFrame(frame)}).catch(()=>{if(next!==this.current||version!==this.switchVersion)return;if(next.paused&&(this.holds.size||document.hidden||!this.g.state.settings.music)){old?.pause();return}this.activeTrack=null;this.current=null;old?.pause()})}
 hold(reason,paused){if(paused)this.holds.add(reason);else this.holds.delete(reason);this.refresh()}
 toggle(){this.g.state.settings.music=!this.g.state.settings.music;this.g.save();this.unlock();this.refresh()}
 setVolume(value,persist=true){this.g.state.settings.musicVolume=Math.max(0,Math.min(1,Number(value)||0));if(this.current)this.current.volume=this.g.state.settings.music?this.g.state.settings.musicVolume:0;if(persist)this.g.save()}
 updateButton(){document.querySelectorAll('[data-act="toggle-music"]').forEach(b=>{b.setAttribute('aria-pressed',String(this.g.state.settings.music));b.setAttribute('title','Musique '+(this.g.state.settings.music?'activée':'désactivée')+' · M');if(b.dataset.musicIcon!==undefined)b.textContent=this.g.state.settings.music?'♫':'♪';else b.textContent=this.g.state.settings.music?'Activée':'Désactivée'})}
 destroy(){this.abort.abort();cancelAnimationFrame(this.fade);for(const audio of this.cache.values())audio.pause();this.cache.clear()}
}
